/**
 * AiAssistant inside the app Shell — an end-to-end page: branded masthead +
 * sidebar nav, content area, and the AI prompt bar docked at the bottom of
 * the content. The assistant's overlays (recent-chat popover + full chat
 * panel) portal into the content area and anchor to its corners.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *
 *   import { ThemeProvider } from "@golden-passport/ds-patternfly";
 *   import { goldenPassport } from "@golden-passport/ds-patternfly";
 *
 *   <ThemeProvider brand={goldenPassport} mode="light" focusRing="outer">
 *     <App />
 *   </ThemeProvider>
 */
import { useState } from "react";
import { Nav, NavItem, NavList } from "@patternfly/react-core";
import {
  AiAssistant,
  Shell,
  shellEnLabels,
} from "@golden-passport/ds-patternfly";

// Replace with your backend call — the thinking indicator shows until the
// returned promise resolves.
async function askAssistant(text: string): Promise<string> {
  await new Promise((r) => setTimeout(r, 900));
  return `You asked: “${text}”. Wire \`onSend\` to your AI backend to answer for real.`;
}

export default function AssistantInShell() {
  // The positioned element the assistant's overlays portal into. Using the
  // content stage (not document.body) keeps the chat panel anchored to the
  // page content, clear of the masthead and sidebar.
  const [stage, setStage] = useState<HTMLDivElement | null>(null);

  return (
    <Shell
      labels={shellEnLabels}
      brandLogo={<strong style={{ fontSize: "1.125rem" }}>Acme Cloud</strong>}
      sidebar={
        <Nav aria-label="Main">
          <NavList>
            <NavItem itemId="overview" isActive>
              Overview
            </NavItem>
            <NavItem itemId="integrations">Integrations</NavItem>
            <NavItem itemId="settings">Settings</NavItem>
          </NavList>
        </Nav>
      }
    >
      <div
        ref={setStage}
        style={{
          position: "relative",
          display: "flex",
          flexDirection: "column",
          minHeight: "70vh",
          padding: "1.5rem",
          gap: "1rem",
        }}
      >
        <h1 style={{ margin: 0 }}>Overview</h1>
        <p style={{ maxWidth: 640 }}>
          Page content lives here. The AI prompt bar is docked below; sending
          a message opens the transient recent-chat popover above it, and the
          History action expands into the full, resizable chat panel anchored
          to this content area.
        </p>
        <div style={{ flex: 1 }} />
        <AiAssistant
          overlayContainer={stage}
          placement="bottom-right"
          persist
          persistKey="acme:ai-assistance"
          onSend={askAssistant}
        />
      </div>
    </Shell>
  );
}

/**
 * Area chart — filled line emphasising cumulative volume over time.
 * Requires @patternfly/react-charts (Victory-based).
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import {
  Chart,
  ChartArea,
  ChartAxis,
  ChartGroup,
  ChartVoronoiContainer,
} from "@patternfly/react-charts/victory";

const single = [
  { x: "Mon", y: 1 }, { x: "Tue", y: 3 }, { x: "Wed", y: 2 },
  { x: "Thu", y: 4 }, { x: "Fri", y: 7 }, { x: "Sat", y: 5 }, { x: "Sun", y: 6 },
];
const series2 = single.map((p) => ({ ...p, y: p.y + 2 }));

export function SingleSeries() {
  return (
    <Chart
      ariaTitle="Run volume"
      ariaDesc="Runs per day, Monday through Sunday."
      height={240}
      padding={{ left: 60, right: 20, top: 20, bottom: 50 }}
      containerComponent={
        <ChartVoronoiContainer
          labels={({ datum }: { datum: { x: string; y: number } }) =>
            `${datum.x}: ${datum.y}`
          }
          constrainToVisibleArea
        />
      }
    >
      <ChartAxis />
      <ChartAxis dependentAxis showGrid />
      <ChartGroup>
        <ChartArea data={single} interpolation="monotoneX" />
      </ChartGroup>
    </Chart>
  );
}

export function MultipleSeries() {
  return (
    <Chart
      ariaTitle="Run volume by env"
      ariaDesc="Run counts for production and staging."
      themeColor="multi"
      height={240}
      padding={{ left: 60, right: 20, top: 20, bottom: 50 }}
    >
      <ChartAxis />
      <ChartAxis dependentAxis showGrid />
      <ChartGroup>
        <ChartArea data={single} interpolation="monotoneX" />
        <ChartArea data={series2} interpolation="monotoneX" />
      </ChartGroup>
    </Chart>
  );
}

export default function AreaChartExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <SingleSeries />
      <MultipleSeries />
    </div>
  );
}

/**
 * Bar chart — discrete categorical comparison, vertical or horizontal.
 * Requires @patternfly/react-charts (Victory-based).
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { Chart, ChartAxis, ChartBar, ChartGroup } from "@patternfly/react-charts/victory";

const data1 = [{ x: "Active", y: 142 }, { x: "Paused", y: 18 }, { x: "Failed", y: 3 }];
const data2 = [{ x: "Active", y: 120 }, { x: "Paused", y: 22 }, { x: "Failed", y: 5 }];

export function GroupedBars() {
  return (
    <Chart
      ariaTitle="Workflow counts"
      ariaDesc="Active, paused, failed across this week and last."
      themeColor="multi"
      height={240}
      domainPadding={{ x: [40, 40] }}
      padding={{ left: 60, right: 20, top: 20, bottom: 50 }}
    >
      <ChartAxis />
      <ChartAxis dependentAxis showGrid />
      <ChartGroup offset={11}>
        <ChartBar data={data1} />
        <ChartBar data={data2} />
      </ChartGroup>
    </Chart>
  );
}

export function Horizontal() {
  return (
    <Chart
      ariaTitle="Status (horizontal)"
      horizontal
      height={240}
      domainPadding={{ y: [40, 40] }}
      padding={{ left: 100, right: 20, top: 20, bottom: 50 }}
    >
      <ChartAxis />
      <ChartAxis dependentAxis showGrid />
      <ChartGroup>
        <ChartBar data={data1} />
      </ChartGroup>
    </Chart>
  );
}

export default function BarChartExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <GroupedBars />
      <Horizontal />
    </div>
  );
}

/**
 * Box plot chart — five-number distribution summaries per category.
 * Requires @patternfly/react-charts and victory (PF6 ships no dedicated
 * ChartBoxPlot wrapper, so Victory's VictoryBoxPlot is composed directly
 * inside a PF6-themed Chart).
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { Chart, ChartAxis } from "@patternfly/react-charts/victory";
import { VictoryBoxPlot } from "victory";

const data = [
  { x: "p50", min: 1, q1: 2, median: 3, q3: 4, max: 5 },
  { x: "p95", min: 2, q1: 3, median: 5, q3: 7, max: 9 },
  { x: "p99", min: 3, q1: 5, median: 8, q3: 12, max: 18 },
];

export function Recipe() {
  return (
    <Chart
      ariaTitle="API latency"
      ariaDesc="p50/p95/p99 latency distributions across last hour."
      height={240}
      domainPadding={{ x: [40, 40] }}
      padding={{ left: 60, right: 20, top: 20, bottom: 50 }}
    >
      <ChartAxis />
      <ChartAxis dependentAxis showGrid />
      <VictoryBoxPlot
        boxWidth={20}
        data={data}
        style={{
          min: { stroke: "var(--pf-t--global--icon--color--regular)" },
          max: { stroke: "var(--pf-t--global--icon--color--regular)" },
          q1: { fill: "var(--pf-t--chart--color--blue--400)" },
          q3: { fill: "var(--pf-t--chart--color--blue--400)" },
          median: { stroke: "var(--pf-t--global--text--color--regular)" },
        }}
      />
    </Chart>
  );
}

export default function BoxPlotChartExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <Recipe />
    </div>
  );
}

/**
 * Bullet chart — single-metric performance vs target with qualitative bands.
 * Requires @patternfly/react-charts (Victory-based).
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { ChartBullet } from "@patternfly/react-charts/victory";

export function Basic() {
  return (
    <ChartBullet
      ariaTitle="SLA: API latency"
      ariaDesc="P99 latency vs 250ms SLA target."
      title="API latency"
      subTitle="p99 (ms)"
      primarySegmentedMeasureData={[{ name: "Actual", y: 180 }]}
      comparativeWarningMeasureData={[{ name: "Warning", y: 200 }]}
      comparativeErrorMeasureData={[{ name: "SLA", y: 250 }]}
      qualitativeRangeData={[
        { name: "Range", y: 150 },
        { name: "Range", y: 220 },
        { name: "Range", y: 300 },
      ]}
      maxDomain={{ y: 300 }}
      height={200}
      width={500}
      padding={{ left: 100, right: 50, top: 60, bottom: 60 }}
    />
  );
}

export default function BulletChartExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <Basic />
    </div>
  );
}

/**
 * Donut chart — parts-of-a-whole with a centred topline number.
 * Requires @patternfly/react-charts (Victory-based).
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { ChartDonut } from "@patternfly/react-charts/victory";

const data = [
  { x: "Active", y: 142 },
  { x: "Paused", y: 18 },
  { x: "Failed", y: 3 },
];

export function CentredTotal() {
  return (
    <ChartDonut
      ariaTitle="Workflows by status"
      ariaDesc="142 active, 18 paused, 3 failed of 163 total."
      data={data}
      labels={({ datum }: { datum: { x: string; y: number } }) =>
        `${datum.x}: ${datum.y}`
      }
      title="163"
      subTitle="Workflows"
      themeColor="multi"
      height={260}
      width={260}
    />
  );
}

export default function DonutChartExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <CentredTotal />
    </div>
  );
}

/**
 * Donut utilization chart — single-metric percentage arc with thresholds.
 * Requires @patternfly/react-charts (Victory-based).
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { ChartDonutUtilization } from "@patternfly/react-charts/victory";

export function ThreeUtilizations() {
  return (
    <div style={{ display: "grid", gap: 16, gridTemplateColumns: "repeat(3, 1fr)" }}>
      <ChartDonutUtilization
        ariaTitle="CPU utilization"
        ariaDesc="35% of CPU capacity used."
        data={{ x: "CPU", y: 35 }}
        title="35%"
        subTitle="CPU"
        thresholds={[{ value: 60 }, { value: 90 }]}
        height={240}
        width={240}
      />
      <ChartDonutUtilization
        ariaTitle="Memory utilization"
        ariaDesc="72% of memory used — past the warning threshold."
        data={{ x: "Memory", y: 72 }}
        title="72%"
        subTitle="Memory"
        thresholds={[{ value: 60 }, { value: 90 }]}
        height={240}
        width={240}
      />
      <ChartDonutUtilization
        ariaTitle="Disk utilization"
        ariaDesc="92% of disk used — past the danger threshold."
        data={{ x: "Disk", y: 92 }}
        title="92%"
        subTitle="Disk"
        thresholds={[{ value: 60 }, { value: 90 }]}
        height={240}
        width={240}
      />
    </div>
  );
}

export default function DonutUtilizationChartExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <ThreeUtilizations />
    </div>
  );
}

/**
 * Legends — colour-to-series keys, auto-placed or standalone.
 * Requires @patternfly/react-charts (Victory-based).
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import {
  Chart,
  ChartArea,
  ChartAxis,
  ChartGroup,
  ChartLegend,
} from "@patternfly/react-charts/victory";

const a = [{ x: 1, y: 2 }, { x: 2, y: 4 }, { x: 3, y: 3 }, { x: 4, y: 5 }];
const b = a.map((p) => ({ ...p, y: p.y + 1 }));
const c = a.map((p) => ({ ...p, y: p.y + 2 }));

const legendData = [{ name: "API" }, { name: "Worker" }, { name: "Queue" }];

export function LegendAtTheBottom() {
  return (
    <Chart
      ariaTitle="Throughput by service"
      ariaDesc="API, Worker, and Queue throughput."
      themeColor="multi"
      height={280}
      padding={{ left: 60, right: 20, top: 20, bottom: 80 }}
      legendData={legendData}
      legendPosition="bottom"
    >
      <ChartAxis />
      <ChartAxis dependentAxis showGrid />
      <ChartGroup>
        <ChartArea data={a} />
        <ChartArea data={b} />
        <ChartArea data={c} />
      </ChartGroup>
    </Chart>
  );
}

export function StandaloneChartLegend() {
  return (
    <ChartLegend
      data={legendData}
      orientation="horizontal"
      height={60}
      width={300}
    />
  );
}

export default function LegendsExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <LegendAtTheBottom />
      <StandaloneChartLegend />
    </div>
  );
}

/**
 * Line chart — the classic trend visualization, values over time.
 * Requires @patternfly/react-charts (Victory-based).
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import {
  Chart,
  ChartAxis,
  ChartGroup,
  ChartLine,
  ChartVoronoiContainer,
} from "@patternfly/react-charts/victory";

const days = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
const series = (n: number) =>
  days.map((x, i) => ({ x, y: n + (i % 4) * 1.5 + (i % 2 === 0 ? 1 : 0) }));

export function TwoSeriesWithTooltip() {
  return (
    <Chart
      ariaTitle="Latency by env"
      ariaDesc="Prod vs staging latency over the past week."
      themeColor="multi"
      height={260}
      padding={{ left: 60, right: 20, top: 20, bottom: 60 }}
      legendData={[{ name: "Prod" }, { name: "Staging" }]}
      legendPosition="bottom"
      containerComponent={
        <ChartVoronoiContainer
          labels={({ datum }: { datum: { x: string; y: number; childName?: string } }) =>
            `${datum.childName ?? "series"} ${datum.x}: ${datum.y.toFixed(1)}`
          }
          constrainToVisibleArea
        />
      }
    >
      <ChartAxis />
      <ChartAxis dependentAxis showGrid />
      <ChartGroup>
        <ChartLine data={series(2)} name="Prod" interpolation="monotoneX" />
        <ChartLine data={series(4)} name="Staging" interpolation="monotoneX" />
      </ChartGroup>
    </Chart>
  );
}

export default function LineChartExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <TwoSeriesWithTooltip />
    </div>
  );
}

/**
 * Chart patterns — SVG fill patterns as a second signal alongside colour.
 *
 * Requires @patternfly/react-charts (Victory wrapper).
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useId } from "react";
import {
  Chart,
  ChartAxis,
  ChartBar,
  ChartGroup,
} from "@patternfly/react-charts/victory";

const data1 = [
  { x: "Q1", y: 40 }, { x: "Q2", y: 70 }, { x: "Q3", y: 55 }, { x: "Q4", y: 80 },
];
const data2 = data1.map((p) => ({ ...p, y: p.y + 12 }));

export function PatternFills() {
  const id = useId();
  const diagId = `${id}-diag`;
  const dotsId = `${id}-dots`;
  return (
    <>
      <svg width={0} height={0} style={{ position: "absolute" }}>
        <defs>
          <pattern id={diagId} patternUnits="userSpaceOnUse" width="6" height="6" patternTransform="rotate(45)">
            <rect width="6" height="6" fill="var(--pf-t--chart--color--blue--400, #06c)" />
            <line x1="0" y1="0" x2="0" y2="6" stroke="white" strokeWidth="2" />
          </pattern>
          <pattern id={dotsId} patternUnits="userSpaceOnUse" width="6" height="6">
            <rect width="6" height="6" fill="var(--pf-t--chart--color--purple--400, #5752d1)" />
            <circle cx="3" cy="3" r="1.2" fill="white" />
          </pattern>
        </defs>
      </svg>
      <Chart
        ariaTitle="Quarterly revenue (patterned)"
        ariaDesc="Two products by quarter, distinguished by diagonal vs dotted fill."
        height={260}
        domainPadding={{ x: [40, 40] }}
        padding={{ left: 60, right: 20, top: 20, bottom: 60 }}
        legendData={[{ name: "Pro" }, { name: "Enterprise" }]}
        legendPosition="bottom"
      >
        <ChartAxis />
        <ChartAxis dependentAxis showGrid />
        <ChartGroup offset={14}>
          <ChartBar data={data1} style={{ data: { fill: `url(#${diagId})` } }} />
          <ChartBar data={data2} style={{ data: { fill: `url(#${dotsId})` } }} />
        </ChartGroup>
      </Chart>
    </>
  );
}

export default function PatternsExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <PatternFills />
    </div>
  );
}

/**
 * Pie chart — composition of a whole; slices that sum to 100%.
 *
 * Requires @patternfly/react-charts (Victory wrapper).
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { ChartContainer, ChartPie } from "@patternfly/react-charts/victory";

const data = [
  { x: "Pro",        y: 60 },
  { x: "Enterprise", y: 25 },
  { x: "Free",       y: 15 },
];

export function Basic() {
  return (
    /* responsive={false} renders the chart at its fixed width×height
       instead of scaling to fill the container — otherwise the SVG
       stretches to the container width and its height balloons. */
    <ChartPie
      ariaTitle="Plan distribution"
      ariaDesc="60% Pro, 25% Enterprise, 15% Free."
      data={data}
      labels={({ datum }: { datum: { x: string; y: number } }) =>
        `${datum.x}: ${datum.y}%`
      }
      themeColor="multi"
      height={260}
      width={440}
      legendData={data.map((d) => ({ name: `${d.x} (${d.y}%)` }))}
      legendPosition="right"
      padding={{ top: 10, bottom: 10, left: 10, right: 160 }}
      containerComponent={<ChartContainer responsive={false} />}
    />
  );
}

export default function PieChartExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <Basic />
    </div>
  );
}

/**
 * Resize observer — a fluid chart that fills its container's width.
 *
 * Requires @patternfly/react-charts (Victory wrapper).
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import {
  Chart,
  ChartArea,
  ChartAxis,
  ChartGroup,
} from "@patternfly/react-charts/victory";

const data = [
  { x: 1, y: 1 }, { x: 2, y: 3 }, { x: 3, y: 2 }, { x: 4, y: 5 }, { x: 5, y: 4 },
];

export function ContainerDrivenWidth() {
  return (
    <div style={{ width: "100%", height: 240 }}>
      <Chart
        ariaTitle="Resizable area"
        ariaDesc="A chart that fills the width of its container."
        height={240}
        padding={{ left: 60, right: 20, top: 20, bottom: 50 }}
        // Omit `width` — Victory's default container reads from layout.
      >
        <ChartAxis />
        <ChartAxis dependentAxis showGrid />
        <ChartGroup>
          <ChartArea data={data} interpolation="monotoneX" />
        </ChartGroup>
      </Chart>
    </div>
  );
}

export default function ResizeObserverExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <ContainerDrivenWidth />
    </div>
  );
}

/**
 * Sankey chart — flow visualization; values moving from one bucket to another.
 *
 * Requires @patternfly/react-charts (ECharts wrapper, beta) and echarts.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useId } from "react";
import { Charts } from "@patternfly/react-charts/echarts";
import * as echarts from "echarts/core";
import { SankeyChart } from "echarts/charts";
import { TitleComponent, TooltipComponent } from "echarts/components";
import { SVGRenderer } from "echarts/renderers";
import { useTheme } from "@golden-passport/ds-patternfly";

// Register only the ECharts pieces the Sankey needs (tree-shakeable).
echarts.use([SankeyChart, SVGRenderer, TitleComponent, TooltipComponent]);

// A realistic SaaS funnel: free trial → activated → paid plans / churn.
const sankeyNodes = [
  { name: "Free trial" },
  { name: "Activated" },
  { name: "Pro" },
  { name: "Enterprise" },
  { name: "Churned" },
];
const sankeyLinks = [
  { source: "Free trial", target: "Activated", value: 480 },
  { source: "Free trial", target: "Churned", value: 220 },
  { source: "Activated", target: "Pro", value: 320 },
  { source: "Activated", target: "Enterprise", value: 90 },
  { source: "Activated", target: "Churned", value: 70 },
];

export function Basic() {
  const id = useId();
  const { mode } = useTheme();
  const labelColor = mode === "dark" ? "#f5f5f5" : "#151515";
  return (
    <Charts
      id={`${id}-sankey-basic`}
      nodeSelector="html"
      height={360}
      width={760}
      option={{
        aria: {
          enabled: true,
          label: {
            description:
              "User funnel: free trial through activation to paid plans and churn.",
          },
        },
        series: [
          {
            type: "sankey",
            data: sankeyNodes,
            links: sankeyLinks,
            label: { color: labelColor },
            lineStyle: { color: "gradient", opacity: 0.4 },
          },
        ],
