}

export default function MaintenanceExample() {
  return <Default />;
}

/**
 * MissingPage (@patternfly/react-component-groups) — a standard 404 page:
 * title, body, and a link back home. Wire it up as the catch-all route in
 * your router.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { MissingPage } from "@patternfly/react-component-groups/dist/dynamic/MissingPage";

export function Default() {
  return (
    <MissingPage
      titleText="Page not found"
      bodyText="The page you're looking for doesn't exist or has moved."
      toHomePageUrl="/"
      toHomePageText="Go home"
    />
  );
}

export default function MissingPageExample() {
  return <Default />;
}

/**
 * ColumnManagementModal (@patternfly/react-component-groups) — a pre-built
 * modal for showing / hiding table columns, with untoggleable "always-on"
 * columns and optional drag-and-drop reorder.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useState } from "react";
import ColumnManagementModal, {
  type ColumnManagementModalColumn,
} from "@patternfly/react-component-groups/dist/dynamic/ColumnManagementModal";
import { Button } from "@golden-passport/ds-patternfly";

const initial: ColumnManagementModalColumn[] = [
  { key: "name",    title: "Name",    isShown: true,  isShownByDefault: true,  isUntoggleable: true },
  { key: "status",  title: "Status",  isShown: true,  isShownByDefault: true },
  { key: "owner",   title: "Owner",   isShown: true,  isShownByDefault: true },
  { key: "created", title: "Created", isShown: false, isShownByDefault: false },
  { key: "updated", title: "Updated", isShown: false, isShownByDefault: false },
  { key: "tags",    title: "Tags",    isShown: false, isShownByDefault: false },
];

export function ToggleColumns() {
  const [open, setOpen] = useState(false);
  const [cols, setCols] = useState(initial);

  return (
    <>
      <div style={{ display: "grid", gap: 8 }}>
        <Button onClick={() => setOpen(true)}>Manage columns</Button>
        <p style={{ margin: 0, color: "var(--gp-color-text-subtle)", fontSize: 13 }}>
          Currently visible:{" "}
          {cols.filter((c) => c.isShown).map((c) => c.title).join(", ")}
        </p>
      </div>
      <ColumnManagementModal
        isOpen={open}
        onClose={() => setOpen(false)}
        appliedColumns={cols}
        applyColumns={(next) => {
          setCols(next);
          setOpen(false);
        }}
        title="Manage columns"
        description="Pick which columns appear in the workflows table."
      />
    </>
  );
}

export default function ColumnManagementModalExample() {
  return <ToggleColumns />;
}

/**
 * FieldBuilder (@patternfly/react-component-groups) — a two-column repeater
 * for dynamic form rows: env vars, tags, key/value pairs, conditions.
 * Manages the add / remove / focus-management chrome; you supply the inputs
 * via a render prop.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useId, useState } from "react";
import { FieldBuilder } from "@patternfly/react-component-groups/dist/dynamic/FieldBuilder";
import { TextInput } from "@golden-passport/ds-patternfly";

// FieldBuilder renders as a PF6 Table. The Table's TDs default to
// `padding-inline: 0`, so the Name / Value columns butt against each other
// and the row edges. Scope a bit of inline padding + a touch more row gap
// to give the inputs room to breathe. PF6 Table cells read their padding
// from CSS custom properties; `pf-m-compact` (used by FieldBuilder's inner
// Table) zeros the inline ones — override the tokens at the wrapper so the
// override survives PF6's own selectors regardless of breakpoint/grid mode.
const fieldBuilderSpacingCss = [
  ".gp-field-builder-demo .pf-v6-c-table {",
  "  --pf-v6-c-table--cell--PaddingInlineStart: 0;",
  "  --pf-v6-c-table--cell--PaddingInlineEnd: 12px;",
  "  --pf-v6-c-table--cell--PaddingBlockStart: 0.75rem;",
  "  --pf-v6-c-table--cell--PaddingBlockEnd: 0.75rem;",
  "}",
  ".gp-field-builder-demo .pf-v6-c-table__td:last-child,",
  ".gp-field-builder-demo .pf-v6-c-table__th:last-child {",
  "  --pf-v6-c-table--cell--PaddingInlineEnd: 0;",
  "}",
].join("\n");

type EnvVar = { key: string; value: string };

export function KeyValueEditor() {
  const id = useId();
  const [vars, setVars] = useState<EnvVar[]>([
    { key: "API_URL", value: "https://api.example.com" },
    { key: "LOG_LEVEL", value: "info" },
  ]);

  const update = (i: number, patch: Partial<EnvVar>) =>
    setVars((prev) => prev.map((v, idx) => (idx === i ? { ...v, ...patch } : v)));

  return (
    <div className="gp-field-builder-demo">
      <style dangerouslySetInnerHTML={{ __html: fieldBuilderSpacingCss }} />
      <FieldBuilder
        label="Environment variables"
        firstColumnLabel="Name"
        secondColumnLabel="Value"
        rowCount={vars.length}
        rowGroupLabelPrefix="Variable"
        fieldBuilderIdPrefix={id}
        onAddRow={() => setVars((p) => [...p, { key: "", value: "" }])}
        onRemoveRow={(_e, i) => setVars((p) => p.filter((_, idx) => idx !== i))}
        addButtonContent="Add variable"
      >
        {(helpers, i) => [
          <TextInput
            key={`k-${i}`}
            ref={helpers.focusRef as React.Ref<HTMLInputElement>}
            aria-label={helpers.firstColumnAriaLabel}
            value={vars[i]?.key ?? ""}
            onChange={(_e, v) => update(i, { key: v })}
          />,
          <TextInput
            key={`v-${i}`}
            aria-label={helpers.secondColumnAriaLabel ?? ""}
            value={vars[i]?.value ?? ""}
            onChange={(_e, v) => update(i, { value: v })}
          />,
        ]}
      </FieldBuilder>
    </div>
  );
}

export function SingleColumn() {
  const id = useId();
  const [tags, setTags] = useState<string[]>(["urgent", "billing"]);
  return (
    <div className="gp-field-builder-demo">
      <style dangerouslySetInnerHTML={{ __html: fieldBuilderSpacingCss }} />
      <FieldBuilder
        label="Tags"
        firstColumnLabel="Tag"
        rowCount={tags.length}
        rowGroupLabelPrefix="Tag"
        fieldBuilderIdPrefix={id}
        onAddRow={() => setTags((p) => [...p, ""])}
        onRemoveRow={(_e, i) => setTags((p) => p.filter((_, idx) => idx !== i))}
        addButtonContent="Add tag"
      >
        {(helpers, i) => (
          <TextInput
            ref={helpers.focusRef as React.Ref<HTMLInputElement>}
            aria-label={helpers.firstColumnAriaLabel}
            value={tags[i] ?? ""}
            onChange={(_e, v) =>
              setTags((p) => p.map((t, idx) => (idx === i ? v : t)))
            }
          />
        )}
      </FieldBuilder>
    </div>
  );
}

export default function FieldBuilderExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <KeyValueEditor />
      <SingleColumn />
    </div>
  );
}

/**
 * ListManager (@patternfly/react-component-groups) — a reusable selectable +
 * reorderable list, the visible body of a column-management or preferences
 * modal. Embed it inline (e.g. inside a Drawer) when you don't want the full
 * ColumnManagementModal.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 *
 * Note: ListManager's drag-and-drop overlay portals into
 * `document.getElementById("root")` — make sure your app mounts in a
 * `<div id="root">` (the typical Vite / CRA default).
 */
import { useState } from "react";
import ListManager, {
  type ListManagerItem,
} from "@patternfly/react-component-groups/dist/dynamic/ListManager";

// Mirrors PF6's canonical ColumnExample for ListManager
// (https://www.patternfly.org/component-groups/helpers/list-manager).
// `isShown` in the upstream sample maps to `isSelected` on the installed
// ListManagerItem — same semantic.
const DEFAULT_COLUMNS: ListManagerItem[] = [
  { key: "id",          title: "ID",           isShownByDefault: true,  isSelected: true,  isUntoggleable: true },
  { key: "publishDate", title: "Publish date", isShownByDefault: true,  isSelected: true },
  { key: "impact",      title: "Impact",       isShownByDefault: true,  isSelected: true },
  { key: "score",       title: "Score",        isShownByDefault: false, isSelected: false },
];

export function ColumnExample() {
  const [columns, setColumns] = useState(DEFAULT_COLUMNS);

  return (
    <ListManager
      columns={columns}
      enableDragDrop
      onOrderChange={setColumns}
      onSelect={(col) =>
        setColumns((prev) =>
          prev.map((c) =>
            c.key === col.key ? { ...c, isSelected: !!col.isSelected } : c,
          ),
        )
      }
      onSelectAll={(newColumns) => setColumns(newColumns)}
      onSave={(newColumns) => {
        setColumns(newColumns);
        alert("Changes saved!");
      }}
      onCancel={() => alert("Changes cancelled!")}
    />
  );
}

export default function ListManagerExample() {
  return <ColumnExample />;
}

/**
 * LogSnippet (@patternfly/react-component-groups) — a small, alert-coloured
 * block for inline error logs and stack traces, for detail panels, error
 * states, or notification drawers.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { LogSnippet } from "@patternfly/react-component-groups/dist/dynamic/LogSnippet";
import { AlertVariant } from "@golden-passport/ds-patternfly";

const sampleLog = `2026-05-10T09:21:14.231Z ERROR  worker-3   Failed to dispatch job 4892
  at WorkflowDispatcher.dispatch (workflow-dispatcher.ts:142)
  at async WorkflowRunner.run (workflow-runner.ts:88)
caused by: ConnectionResetError: connection closed by upstream`;

export function DefaultDanger() {
  return (
    <LogSnippet
      message="The job failed during dispatch."
      logSnippet={sampleLog}
      variant={AlertVariant.danger}
    />
  );
}

export function OtherVariants() {
  return (
    <LogSnippet
      message="Run completed with warnings."
      logSnippet="WARN  step 2 took 14.2s (threshold: 10s)"
      variant={AlertVariant.warning}
    />
  );
}

export default function LogSnippetExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <DefaultDanger />
      <OtherVariants />
    </div>
  );
}

