export type TextInputProps = ComponentPropsWithoutRef<typeof PFTextInput>;

export const TextInput: ForwardRefExoticComponent<
  TextInputProps & RefAttributes<ComponentRef<typeof PFTextInput>>
> = forwardRef<ComponentRef<typeof PFTextInput>, TextInputProps>(
  function TextInput(props, ref) {
    return <PFTextInput ref={ref} {...props} />;
  },
);

