}

export function InlineLink() {
  return (
    <Hint>
      <HintBody>
        Tip: hold Shift to select a range of tasks. See the{" "}
        <Hyperlink href="/docs/selection">
          selection model
        </Hyperlink>{" "}
        for the full keyboard reference.
      </HintBody>
    </Hint>
