/**
 * DS Masthead — PatternFly 6 Masthead under the Golden Passport dials.
 * Thin wrapper: the dial CSS (src/styles) already brands it; add DS
 * defaults here when the design system diverges from stock PF6.
 * No ref: PF6's Masthead is a plain function component (nothing to forward).
 * Generated by scripts/gen-pf-wrappers.mjs — hand-maintained after that.
 */
import { Masthead as PFMasthead } from "@patternfly/react-core";
import type { ComponentPropsWithoutRef } from "react";

export type MastheadProps = ComponentPropsWithoutRef<typeof PFMasthead>;

export function Masthead(props: MastheadProps) {
  return <PFMasthead {...props} />;
}

export {
  MastheadBrand,
  MastheadContent,
  MastheadLogo,
  MastheadMain,
  MastheadToggle,
} from "@patternfly/react-core";

