/**
 * Masthead — the top bar of an app: left brand region (logo + optional
 * sidebar toggle) and a right region for global actions, search, user
 * menu and notifications. Renders as <header> for landmark semantics.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useId, useState } from "react";
import {
  Avatar,
  Button,
  Dropdown,
  DropdownItem,
  DropdownList,
  Masthead,
  MastheadBrand,
  MastheadContent,
  MastheadLogo,
  MastheadMain,
  MastheadToggle,
  MenuToggle,
  type MenuToggleElement,
  Nav,
  NavItem,
  NavList,
  OverflowMenu,
  OverflowMenuContent,
  OverflowMenuControl,
  OverflowMenuGroup,
  OverflowMenuItem,
  PageToggleButton,
  Toolbar,
  ToolbarContent,
  ToolbarItem,
} from "@golden-passport/ds-patternfly";
import { BellIcon, CogIcon, EllipsisVIcon } from "@patternfly/react-icons";

/**
 * Demo brand mark. Real apps render a PF6 <Brand> pointing at their hosted
 * logo asset; an inline SVG keeps this example asset-free, with the
 * wordmark inheriting the theme's text colour.
 */
function AcmeLogo() {
  return (
    <span style={{ display: "inline-flex", alignItems: "center", gap: 10 }}>
      <svg
        viewBox="0 0 40 40"
        width={36}
        height={36}
        aria-hidden="true"
        focusable="false"
      >
        <circle cx="20" cy="20" r="20" fill="#0066cc" />
        <path
          d="M11 28 L20 10 L29 28 M14.5 22 L25.5 22"
          stroke="white"
          strokeWidth={3}
          strokeLinecap="round"
          strokeLinejoin="round"
          fill="none"
        />
      </svg>
      <span
        style={{
          fontSize: 17,
          fontWeight: 700,
          letterSpacing: -0.5,
          color: "var(--gp-color-text-regular)",
        }}
      >
        Acme
      </span>
    </span>
  );
}

// Inline-SVG avatar (Acme brand blue) so the masthead profile menu is
// asset-free. Initials centred via dominant-baseline.
const AVATAR_SRC =
  "data:image/svg+xml;utf8," +
  encodeURIComponent(
    `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'>` +
      `<circle cx='20' cy='20' r='20' fill='#0066cc'/>` +
      `<text x='20' y='20' text-anchor='middle' dominant-baseline='central' ` +
      `font-family='-apple-system,Segoe UI,sans-serif' font-size='15' ` +
      `font-weight='600' fill='white'>AF</text></svg>`,
  );

export function BasicMasthead() {
  const id = useId();
  // The masthead utility icons live in an OverflowMenu that collapses to
  // this kebab dropdown below the breakpoint.
  const [isUtilityKebabOpen, setIsUtilityKebabOpen] = useState(false);
  // Top-right user avatar + profile dropdown.
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);

  return (
    <Masthead id={`${id}-masthead`} display={{ default: "inline" }}>
      <MastheadMain>
        <MastheadToggle>
          <PageToggleButton
            isHamburgerButton
            aria-label="Global navigation"
            id={`${id}-toggle`}
          />
        </MastheadToggle>
        <MastheadBrand>
          <MastheadLogo component="a" href="#">
            <AcmeLogo />
          </MastheadLogo>
        </MastheadBrand>
      </MastheadMain>
      <MastheadContent>
        <Toolbar isStatic id={`${id}-toolbar`}>
          <ToolbarContent>
            <ToolbarItem align={{ default: "alignEnd" }}>
              {/* OverflowMenu shows the utility icons inline above md;
                  below md they collapse into the 3-dot kebab dropdown
                  (OverflowMenuControl). */}
              <OverflowMenu breakpoint="md">
                <OverflowMenuContent>
                  <OverflowMenuGroup groupType="icon">
                    <OverflowMenuItem>
                      <Button
                        variant="plain"
                        aria-label="Notifications"
                        icon={<BellIcon />}
                      />
                    </OverflowMenuItem>
                    <OverflowMenuItem>
                      <Button
                        variant="plain"
                        aria-label="Settings"
                        icon={<CogIcon />}
                      />
                    </OverflowMenuItem>
                  </OverflowMenuGroup>
                </OverflowMenuContent>
                <OverflowMenuControl>
                  <Dropdown
                    isOpen={isUtilityKebabOpen}
                    onSelect={() => setIsUtilityKebabOpen(false)}
                    onOpenChange={(open: boolean) =>
                      setIsUtilityKebabOpen(open)
                    }
                    popperProps={{ position: "right" }}
                    toggle={(toggleRef: React.Ref<MenuToggleElement>) => (
                      <MenuToggle
                        ref={toggleRef}
                        aria-label="More actions"
                        variant="plain"
                        isExpanded={isUtilityKebabOpen}
                        onClick={() => setIsUtilityKebabOpen((v) => !v)}
                        icon={<EllipsisVIcon />}
                      />
                    )}
                  >
                    <DropdownList>
                      <DropdownItem icon={<BellIcon />}>
                        Notifications
                      </DropdownItem>
                      <DropdownItem icon={<CogIcon />}>Settings</DropdownItem>
                    </DropdownList>
                  </Dropdown>
                </OverflowMenuControl>
              </OverflowMenu>
            </ToolbarItem>
            {/* Top-right user avatar + profile dropdown. */}
            <ToolbarItem>
              <Dropdown
                isOpen={isUserMenuOpen}
                onSelect={() => setIsUserMenuOpen(false)}
                onOpenChange={(open: boolean) => setIsUserMenuOpen(open)}
                popperProps={{ position: "right" }}
                toggle={(toggleRef: React.Ref<MenuToggleElement>) => (
                  <MenuToggle
                    ref={toggleRef}
                    aria-label="User menu"
                    variant="plain"
                    className="gp-user-menu-toggle"
                    isExpanded={isUserMenuOpen}
                    onClick={() => setIsUserMenuOpen((v) => !v)}
                    icon={
                      // alt="" — the visible name beside it is the
                      // accessible label; a duplicate alt trips axe
                      // image-redundant-alt.
                      <Avatar src={AVATAR_SRC} alt="" size="md" />
                    }
                  >
                    {/* Name hides below the masthead mobile breakpoint →
                        the toggle collapses to just the avatar. */}
                    <span className="gp-masthead-username">
                      Aliyah Frazier
                    </span>
                  </MenuToggle>
                )}
              >
                <DropdownList>
                  <DropdownItem>My profile</DropdownItem>
                  <DropdownItem>User management</DropdownItem>
                  <DropdownItem>Logout</DropdownItem>
                </DropdownList>
              </Dropdown>
            </ToolbarItem>
          </ToolbarContent>
        </Toolbar>
      </MastheadContent>
    </Masthead>
  );
}

export function StackedMasthead() {
  const id = useId();

  return (
    <Masthead id={`${id}-masthead`} display={{ default: "stack" }}>
      <MastheadMain>
        <MastheadToggle>
          <PageToggleButton
            isHamburgerButton
            aria-label="Global navigation"
            id={`${id}-toggle`}
          />
        </MastheadToggle>
        <MastheadBrand>
          <MastheadLogo component="a" href="#">
            <AcmeLogo />
          </MastheadLogo>
        </MastheadBrand>
      </MastheadMain>
      <MastheadContent>
        <span style={{ color: "var(--gp-color-text-subtle)" }}>
          Stacked content row
        </span>
      </MastheadContent>
    </Masthead>
  );
}

// Two header-surface treatments for a "unified surface" shell — the flat
// sidebar + content layout where sidebar, content and page all share ONE
// flat background; the only question is how the header meets that body:
//   • "flat"   — the masthead shares the same surface, no divider (seamless).
//   • "lifted" — the masthead floats above the flat body via a 1px bottom
//                border + soft shadow, so the header still reads as
//                distinct chrome.
function UnifiedHeaderVariant({ variant }: { variant: "flat" | "lifted" }) {
  const lifted = variant === "lifted";
  // attribute selectors — useId values contain ":" which breaks #id
  // selectors, but [id="…"] matches them fine
  const id = useId();
  const css = `
    [id="${id}"] {
      background: var(--gp-color-bg-primary-default);
      border: 1px solid var(--gp-color-border-subtle);
      border-radius: 8px;
      overflow: hidden;
    }
    /* Sidebar + content + header all share the one flat surface. */
    [id="${id}"] .pf-v6-c-masthead {
      background: var(--gp-color-bg-primary-default);
      ${
        lifted
          ? `border-block-end: 1px solid var(--gp-color-border-subtle);
             box-shadow: 0 2px 6px rgb(0 0 0 / 0.12);`
          : `border-block-end: none; box-shadow: none;`
      }
    }
  `;
  return (
    <div style={{ display: "grid", gap: 8 }}>
      <span style={{ fontWeight: 600, color: "var(--gp-color-text-regular)" }}>
        {lifted ? "Lifted header" : "Flat header"}
      </span>
      <div id={id}>
        <style dangerouslySetInnerHTML={{ __html: css }} />
        <Masthead id={`${id}-masthead`} display={{ default: "inline" }}>
          <MastheadMain>
            <MastheadBrand>
              <MastheadLogo component="a" href="#">
                <AcmeLogo />
              </MastheadLogo>
            </MastheadBrand>
          </MastheadMain>
          <MastheadContent>
            <span style={{ color: "var(--gp-color-text-subtle)" }}>Actions</span>
          </MastheadContent>
        </Masthead>
        <div style={{ display: "flex", minHeight: 150 }}>
          <div style={{ width: 150, padding: 12 }}>
            <Nav aria-label={`${variant} unified-header demo nav`}>
              <NavList>
                <NavItem itemId={0} isActive>Dashboard</NavItem>
                <NavItem itemId={1}>Workflows</NavItem>
                <NavItem itemId={2}>Reports</NavItem>
              </NavList>
            </Nav>
          </div>
          <div
            style={{
              flex: 1,
              padding: 16,
              color: "var(--gp-color-text-subtle)",
            }}
          >
            Sidebar + content share one flat surface.
          </div>
        </div>
      </div>
    </div>
  );
}

export function HeaderSurface() {
  return (
    <div
      style={{
        display: "grid",
        gap: 24,
        gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))",
      }}
    >
      <UnifiedHeaderVariant variant="flat" />
      <UnifiedHeaderVariant variant="lifted" />
    </div>
  );
}

export function Inset() {
  const id = useId();

  return (
    <Masthead
      id={`${id}-masthead`}
      display={{ default: "inline" }}
      inset={{ default: "insetSm" }}
    >
      <MastheadMain>
        <MastheadBrand>
          <MastheadLogo component="a" href="#">
            <AcmeLogo />
          </MastheadLogo>
        </MastheadBrand>
      </MastheadMain>
      <MastheadContent>
        <span style={{ color: "var(--gp-color-text-subtle)" }}>
          inset=&quot;insetSm&quot;
        </span>
      </MastheadContent>
    </Masthead>
  );
}

export default function MastheadExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <BasicMasthead />
      <StackedMasthead />
      <HeaderSurface />
      <Inset />
    </div>
  );
}

/**
 * Application launcher — a grid-style menu of applications (the typical
 * "9-dot" launcher in a masthead), composed from Dropdown + DropdownGroup.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useState } from "react";
import {
  Divider,
  Dropdown,
  DropdownGroup,
  DropdownItem,
  DropdownList,
  MenuToggle,
} from "@golden-passport/ds-patternfly";
import {
  ChartBarIcon,
  CodeBranchIcon,
  CogIcon,
  CubesIcon,
  RocketIcon,
  ServerIcon,
  TableIcon,
  ThIcon,
  UsersIcon,
} from "@patternfly/react-icons";

export function Demo() {
  const [open, setOpen] = useState(false);

  return (
    <Dropdown
      isOpen={open}
      onSelect={() => setOpen(false)}
      onOpenChange={setOpen}
      popperProps={{ position: "right" }}
      toggle={(toggleRef) => (
        <MenuToggle
          ref={toggleRef}
          aria-label="Application launcher"
          variant="plain"
          onClick={() => setOpen((o) => !o)}
          isExpanded={open}
          icon={<ThIcon />}
        />
      )}
    >
      <DropdownGroup label="Core">
        <DropdownList>
          <DropdownItem icon={<RocketIcon />}>Workflows</DropdownItem>
          <DropdownItem icon={<CodeBranchIcon />}>Pipelines</DropdownItem>
          <DropdownItem icon={<TableIcon />}>Datasets</DropdownItem>
          <DropdownItem icon={<ChartBarIcon />}>Insights</DropdownItem>
        </DropdownList>
      </DropdownGroup>
      <Divider />
      <DropdownGroup label="Admin">
        <DropdownList>
          <DropdownItem icon={<ServerIcon />}>Environments</DropdownItem>
          <DropdownItem icon={<UsersIcon />}>Members</DropdownItem>
          <DropdownItem icon={<CubesIcon />}>Resources</DropdownItem>
          <DropdownItem icon={<CogIcon />}>Settings</DropdownItem>
        </DropdownList>
      </DropdownGroup>
    </Dropdown>
  );
}

export default function ApplicationLauncherExample() {
  return <Demo />;
}

/**
 * Context selector — a scoped switcher (workspace / project / organisation)
 * composed from Select + an inline SearchInput above the list.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useId, useMemo, useState } from "react";
import type { CSSProperties, Ref } from "react";
import {
  Divider,
  MenuToggle,
  type MenuToggleElement,
  SearchInput,
  Select,
  SelectGroup,
  SelectList,
  SelectOption,
} from "@golden-passport/ds-patternfly";
import { CheckIcon } from "@patternfly/react-icons";

type Workspace = { id: string; name: string; section: "Recent" | "All" };

const allWorkspaces: Workspace[] = [
  { id: "ws-acme", name: "Acme", section: "Recent" },
  { id: "ws-beta", name: "Beta Lab", section: "Recent" },
  { id: "ws-globex", name: "Globex", section: "All" },
  { id: "ws-initech", name: "Initech", section: "All" },
  { id: "ws-massive", name: "Massive Dynamic", section: "All" },
  { id: "ws-soylent", name: "Soylent", section: "All" },
];

export function Demo() {
  const selectId = useId();
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState<Workspace>(allWorkspaces[0]!);
  const [filter, setFilter] = useState("");

  const filtered = useMemo(() => {
    const q = filter.toLowerCase();
    return allWorkspaces.filter((w) => w.name.toLowerCase().includes(q));
  }, [filter]);

  const recent = filtered.filter((w) => w.section === "Recent");
  const all = filtered.filter((w) => w.section === "All");

  return (
    <Select
      id={selectId}
      isOpen={open}
      selected={active.id}
      onSelect={(_e, value) => {
        const next = allWorkspaces.find((w) => w.id === value);
        if (next) setActive(next);
        setOpen(false);
      }}
      onOpenChange={setOpen}
      toggle={(toggleRef: Ref<MenuToggleElement>) => (
        <MenuToggle
          ref={toggleRef}
          onClick={() => setOpen((o) => !o)}
          isExpanded={open}
          style={{ width: 280 } as CSSProperties}
        >
          <strong style={{ marginInlineEnd: 8 }}>Workspace:</strong>
          {active.name}
        </MenuToggle>
      )}
    >
      <div style={{ padding: 8 }}>
        <SearchInput
          placeholder="Filter workspaces…"
          value={filter}
          onChange={(_e, v) => setFilter(v)}
          onClear={() => setFilter("")}
          aria-label="Filter workspaces"
        />
      </div>
      <Divider />
      {recent.length > 0 && (
        <SelectGroup label="Recent">
          <SelectList>
            {recent.map((w) => (
              <SelectOption
                key={w.id}
                value={w.id}
                isSelected={w.id === active.id}
              >
                {w.id === active.id ? (
                  <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
                    <CheckIcon /> {w.name}
                  </span>
                ) : (
                  w.name
                )}
              </SelectOption>
            ))}
          </SelectList>
        </SelectGroup>
      )}
      {all.length > 0 && (
        <SelectGroup label="All workspaces">
          <SelectList>
            {all.map((w) => (
              <SelectOption
                key={w.id}
                value={w.id}
                isSelected={w.id === active.id}
              >
                {w.name}
              </SelectOption>
            ))}
          </SelectList>
        </SelectGroup>
      )}
      {filtered.length === 0 && (
        <SelectList>
          <SelectOption isAriaDisabled value="">
            No matches for &ldquo;{filter}&rdquo;
          </SelectOption>
        </SelectList>
      )}
    </Select>
  );
}

export default function ContextSelectorExample() {
  return <Demo />;
}

/**
 * Custom menus — recipes built on the Menu primitive that don't fit one of
 * the higher-level wrappers (Dropdown, Select): a search-filtered command
 * palette, a menu with a sticky footer, and a grouped scrollable list.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useState } from "react";
import {
  Button,
  Divider,
  Menu,
  MenuContent,
  MenuFooter,
  MenuGroup,
  MenuItem,
  MenuList,
  MenuSearch,
  MenuSearchInput,
  SearchInput,
} from "@golden-passport/ds-patternfly";

const allCommands = [
  "Run workflow",
  "Run pipeline",
  "Schedule run",
  "View logs",
  "Edit configuration",
  "Duplicate workflow",
  "Archive workflow",
  "Delete workflow",
];

export function FilterSearchPalette() {
  const [filter, setFilter] = useState("");
  const filtered = allCommands.filter((i) =>
    i.toLowerCase().includes(filter.toLowerCase()),
  );

  return (
    <Menu style={{ maxWidth: 360 }}>
      <MenuSearch>
        <MenuSearchInput>
          <SearchInput
            placeholder="Type a command…"
            value={filter}
            onChange={(_e, v) => setFilter(v)}
            onClear={() => setFilter("")}
            aria-label="Filter commands"
          />
        </MenuSearchInput>
      </MenuSearch>
      <Divider />
      <MenuContent>
        <MenuList>
          {filtered.length === 0 ? (
            <MenuItem isAriaDisabled>
              No commands match &ldquo;{filter}&rdquo;
            </MenuItem>
          ) : (
            filtered.map((label, i) => (
              <MenuItem key={label} itemId={i}>
                {label}
              </MenuItem>
            ))
          )}
        </MenuList>
      </MenuContent>
    </Menu>
  );
}

export function WithFooter() {
  const [active, setActive] = useState<number | string>(0);

  return (
    <Menu
      activeItemId={active}
      onSelect={(_e, id) => setActive(id ?? 0)}
      style={{ maxWidth: 320 }}
    >
      <MenuContent>
        <MenuList>
          {Array.from({ length: 5 }).map((_, i) => (
            <MenuItem key={i} itemId={i}>
              Recent run #{1284 - i}
            </MenuItem>
          ))}
        </MenuList>
      </MenuContent>
      <Divider />
      <MenuFooter>
        <Button variant="link" isInline>
          View all 137 runs →
        </Button>
      </MenuFooter>
    </Menu>
  );
}

export function GroupedScrollable() {
  return (
    <Menu isScrollable style={{ maxHeight: 240, maxWidth: 320 }}>
      <MenuContent>
        <MenuGroup label="Today">
          <MenuList>
            <MenuItem>Run #1284 — succeeded</MenuItem>
            <MenuItem>Run #1283 — succeeded</MenuItem>
          </MenuList>
        </MenuGroup>
        <Divider />
        <MenuGroup label="Yesterday">
          <MenuList>
            <MenuItem>Run #1282 — failed</MenuItem>
            <MenuItem>Run #1281 — succeeded</MenuItem>
            <MenuItem>Run #1280 — succeeded</MenuItem>
          </MenuList>
        </MenuGroup>
        <Divider />
        <MenuGroup label="Earlier this week">
          <MenuList>
            {Array.from({ length: 8 }).map((_, i) => (
              <MenuItem key={i}>Run #{1279 - i} — succeeded</MenuItem>
            ))}
          </MenuList>
        </MenuGroup>
      </MenuContent>
    </Menu>
  );
}

export default function CustomMenusExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <FilterSearchPalette />
      <WithFooter />
      <GroupedScrollable />
    </div>
  );
}

