/**
 * Bullseye — centers a single child both vertically and horizontally within
 * its parent. The classic use is empty states, loading spinners, and error
 * screens.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import type { CSSProperties } from "react";
import { Bullseye } from "@golden-passport/ds-patternfly";

// Shaded placeholder block so the centered content is visible in the demo.
// In a real app this is your empty state / spinner / error message.
function Box({ label, style }: { label: string; style?: CSSProperties }) {
  return (
    <div
      style={{
        background: "var(--gp-color-brand-default)",
        color: "var(--gp-color-brand-on)",
        padding: "12px 16px",
        borderRadius: "var(--gp-radius-sm)",
        fontSize: 14,
        textAlign: "center",
        ...style,
      }}
    >
      {label}
    </div>
  );
}

export function LiveDemo() {
  return (
    <Bullseye>
      <Box label="centered" style={{ minWidth: 160 }} />
    </Bullseye>
  );
}

export default function BullseyeExample() {
  return (
    <div style={{ height: 240 }}>
      <LiveDemo />
    </div>
  );
}

/**
 * Flex — general-purpose flex container with a token-aware API: spacing,
 * direction, alignment, and justification are all set per breakpoint.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { Flex, FlexItem } from "@golden-passport/ds-patternfly";

// Shaded placeholder block so the layout regions are visible in the demo.
// In a real app these are your buttons / labels / panels.
function Box({ label }: { label: string }) {
  return (
    <div
      style={{
        background: "var(--gp-color-brand-default)",
        color: "var(--gp-color-brand-on)",
        padding: "12px 16px",
        borderRadius: "var(--gp-radius-sm)",
        fontSize: 14,
        textAlign: "center",
      }}
    >
      {label}
    </div>
  );
}

export function BasicRow() {
  return (
    <Flex spaceItems={{ default: "spaceItemsMd" }}>
      <FlexItem><Box label="A" /></FlexItem>
      <FlexItem><Box label="B" /></FlexItem>
      <FlexItem><Box label="C" /></FlexItem>
    </Flex>
  );
}

export function PushingItemsApart() {
  return (
    <Flex
      justifyContent={{ default: "justifyContentSpaceBetween" }}
      alignItems={{ default: "alignItemsCenter" }}
    >
      <FlexItem><Box label="left" /></FlexItem>
      <FlexItem><Box label="center" /></FlexItem>
      <FlexItem><Box label="right" /></FlexItem>
    </Flex>
  );
}

export function ColumnDirection() {
  return (
    <Flex
      direction={{ default: "column" }}
      spaceItems={{ default: "spaceItemsSm" }}
    >
      <FlexItem><Box label="top" /></FlexItem>
      <FlexItem><Box label="middle" /></FlexItem>
      <FlexItem><Box label="bottom" /></FlexItem>
    </Flex>
  );
}

export function FillingRemainingSpace() {
  return (
    <Flex spaceItems={{ default: "spaceItemsMd" }}>
      <FlexItem><Box label="fixed" /></FlexItem>
      <FlexItem grow={{ default: "grow" }}>
        <Box label="grows to fill" />
      </FlexItem>
      <FlexItem><Box label="fixed" /></FlexItem>
    </Flex>
  );
}

export default function FlexExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <BasicRow />
      <PushingItemsApart />
      <ColumnDirection />
      <FillingRemainingSpace />
    </div>
  );
}

/**
 * Gallery — responsive grid of equal-width tiles. You specify the minimum
 * tile width; the browser computes the column count at every viewport size.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { Gallery, GalleryItem } from "@golden-passport/ds-patternfly";

// Shaded placeholder tile so the gallery cells are visible in the demo.
// In a real app these are your cards / dashboard widgets.
function Box({ label }: { label: string }) {
  return (
    <div
      style={{
        background: "var(--gp-color-brand-default)",
        color: "var(--gp-color-brand-on)",
        padding: 24,
        borderRadius: "var(--gp-radius-sm)",
        fontSize: 14,
        textAlign: "center",
      }}
    >
      {label}
    </div>
  );
}

export function DefaultBehavior() {
  return (
    <Gallery hasGutter minWidths={{ default: "180px" }}>
      {Array.from({ length: 8 }).map((_, i) => (
        <GalleryItem key={i}>
          <Box label={`tile ${i + 1}`} />
        </GalleryItem>
      ))}
    </Gallery>
  );
}

export function PerBreakpointMinWidths() {
  return (
    <Gallery
      hasGutter
      minWidths={{
        default: "140px",
        md: "200px",
        lg: "260px",
      }}
    >
      {Array.from({ length: 6 }).map((_, i) => (
        <GalleryItem key={i}>
          <Box label={`tile ${i + 1}`} />
        </GalleryItem>
      ))}
    </Gallery>
  );
}

export default function GalleryExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <DefaultBehavior />
      <PerBreakpointMinWidths />
    </div>
  );
}

/**
 * Grid — 12-column grid with per-breakpoint span controls. Use it when items
 * have distinct widths and you want the layout expressed in column units.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { Grid, GridItem } from "@golden-passport/ds-patternfly";

// Shaded placeholder block so the grid cells are visible in the demo.
// In a real app these are your charts / stats / form fields.
function Box({ label }: { label: string }) {
  return (
    <div
      style={{
        background: "var(--gp-color-brand-default)",
        color: "var(--gp-color-brand-on)",
        padding: "12px 16px",
        borderRadius: "var(--gp-radius-sm)",
        fontSize: 14,
        textAlign: "center",
      }}
    >
      {label}
    </div>
  );
}

export function EqualColumns() {
  return (
    <Grid hasGutter span={4}>
      <GridItem><Box label="span 4" /></GridItem>
      <GridItem><Box label="span 4" /></GridItem>
      <GridItem><Box label="span 4" /></GridItem>
    </Grid>
  );
}

export function MixedSpans() {
  return (
    <Grid hasGutter>
      <GridItem span={8}><Box label="span 8 — wide chart" /></GridItem>
      <GridItem span={4}><Box label="span 4 — stat" /></GridItem>
      <GridItem span={3}><Box label="3" /></GridItem>
      <GridItem span={3}><Box label="3" /></GridItem>
      <GridItem span={3}><Box label="3" /></GridItem>
      <GridItem span={3}><Box label="3" /></GridItem>
    </Grid>
  );
}

export function ResponsiveSpans() {
  return (
    <Grid hasGutter>
      {Array.from({ length: 6 }).map((_, i) => (
        <GridItem key={i} span={12} md={6} lg={4}>
          <Box label={`item ${i + 1}`} />
        </GridItem>
      ))}
    </Grid>
  );
}

export default function GridExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <EqualColumns />
      <MixedSpans />
      <ResponsiveSpans />
    </div>
  );
}

/**
 * Level — single horizontal row that distributes its children with
 * justify-content: space-between. The classic use is a header bar with a
 * title on the left and actions on the right.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { Level, LevelItem } from "@golden-passport/ds-patternfly";

// Shaded placeholder block so the row items are visible in the demo.
// In a real app these are your titles / buttons / metadata.
function Box({ label }: { label: string }) {
  return (
    <div
      style={{
        background: "var(--gp-color-brand-default)",
        color: "var(--gp-color-brand-on)",
        padding: "12px 16px",
        borderRadius: "var(--gp-radius-sm)",
        fontSize: 14,
        textAlign: "center",
      }}
    >
      {label}
    </div>
  );
}

export function TwoEnds() {
  return (
    <Level>
      <LevelItem>
        <strong style={{ fontSize: 18 }}>Tasks</strong>
      </LevelItem>
      <LevelItem>
        <Box label="Create task" />
      </LevelItem>
    </Level>
  );
}

export function ThreeOrMoreItems() {
  return (
    <Level>
      <LevelItem><Box label="left" /></LevelItem>
      <LevelItem><Box label="middle" /></LevelItem>
      <LevelItem><Box label="right" /></LevelItem>
    </Level>
  );
}

export default function LevelExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <TwoEnds />
      <ThreeOrMoreItems />
    </div>
  );
}

/**
 * Split — horizontal row where one item fills remaining space and the others
 * stay intrinsic. The classic use is a sidebar + content row, or a row with
 * a flexible label that pushes trailing icons to the end.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import type { CSSProperties } from "react";
import { Split, SplitItem } from "@golden-passport/ds-patternfly";

// Shaded placeholder block so the row segments are visible in the demo.
// In a real app these are your sidebar / content / action contents.
function Box({ label, style }: { label: string; style?: CSSProperties }) {
  return (
    <div
      style={{
        background: "var(--gp-color-brand-default)",
        color: "var(--gp-color-brand-on)",
        padding: "12px 16px",
        borderRadius: "var(--gp-radius-sm)",
        fontSize: 14,
        textAlign: "center",
        ...style,
      }}
    >
      {label}
    </div>
  );
}

export function OneFilledItem() {
  return (
    <Split hasGutter>
      <SplitItem><Box label="sidebar" style={{ minWidth: 120 }} /></SplitItem>
      <SplitItem isFilled>
        <Box label="main content — fills remaining width" />
      </SplitItem>
    </Split>
  );
}

export function FilledMiddle() {
  return (
    <Split hasGutter>
      <SplitItem><Box label="leading icon" style={{ minWidth: 80 }} /></SplitItem>
      <SplitItem isFilled><Box label="flexible label" /></SplitItem>
      <SplitItem><Box label="action" style={{ minWidth: 80 }} /></SplitItem>
    </Split>
  );
}

export default function SplitExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <OneFilledItem />
      <FilledMiddle />
    </div>
  );
}

/**
 * Stack — vertical layout where children stack top-to-bottom and exactly one
 * item can be marked isFilled to consume remaining vertical space.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { Stack, StackItem } from "@golden-passport/ds-patternfly";

// Shaded placeholder block so the layout regions are visible in the demo.
// In a real app these are your header / footer / row contents.
function Box({ label }: { label: string }) {
  return (
    <div
      style={{
        background: "var(--gp-color-brand-default)",
        color: "var(--gp-color-brand-on)",
        padding: "12px 16px",
        borderRadius: "var(--gp-radius-sm)",
        fontSize: 14,
        textAlign: "center",
      }}
    >
      {label}
    </div>
  );
}

export function PageChrome() {
  return (
    <Stack hasGutter style={{ height: "100%" }}>
      <StackItem><Box label="header" /></StackItem>
      <StackItem isFilled>
        <div
          style={{
            background: "var(--gp-color-bg-primary-default)",
            border: "1px solid var(--gp-color-border-subtle)",
            borderRadius: "var(--gp-radius-sm)",
            padding: 24,
            height: "100%",
            color: "var(--gp-color-text-regular)",
          }}
        >
          body — fills remaining height
        </div>
      </StackItem>
      <StackItem><Box label="footer" /></StackItem>
    </Stack>
  );
}

export function VerticalList() {
  return (
    <Stack hasGutter>
      <StackItem><Box label="row 1" /></StackItem>
      <StackItem><Box label="row 2" /></StackItem>
      <StackItem><Box label="row 3" /></StackItem>
    </Stack>
  );
}

export default function StackExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <div style={{ height: 320 }}>
        <PageChrome />
      </div>
      <VerticalList />
    </div>
  );
}
